   170	endmodule=========== core/CtrlUnit.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	
     4	module CtrlUnit(
     5	    input[31:0] inst,
     6	    input cmp_res,
     7	    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
     8	        MIO, rs1use, rs2use,
     9	    output [1:0] hazard_optype,
    10	    output [2:0] ImmSel, cmp_ctrl,
    11	    output [3:0] ALUControl,
    12	    output JALR
    13	);
    14	
    15	    wire[6:0] funct7 = inst[31:25];
    16	    wire[2:0] funct3 = inst[14:12];
    17	    wire[6:0] opcode = inst[6:0];
    18	
    19	    wire Rop = opcode == 7'b0110011;
    20	    wire Iop = opcode == 7'b0010011;
    21	    wire Bop = opcode == 7'b1100011;
    22	    wire Lop = opcode == 7'b0000011;
    23	    wire Sop = opcode == 7'b0100011;
    24	
    25	    wire funct7_0  = funct7 == 7'h0;
    26	    wire funct7_32 = funct7 == 7'h20;
    27	
    28	    wire funct3_0 = funct3 == 3'h0;
    29	    wire funct3_1 = funct3 == 3'h1;
    30	    wire funct3_2 = funct3 == 3'h2;
    31	    wire funct3_3 = funct3 == 3'h3;
    32	    wire funct3_4 = funct3 == 3'h4;
    33	    wire funct3_5 = funct3 == 3'h5;
    34	    wire funct3_6 = funct3 == 3'h6;
    35	    wire funct3_7 = funct3 == 3'h7;
    36	
    37	    wire ADD  = Rop & funct3_0 & funct7_0;
    38	    wire SUB  = Rop & funct3_0 & funct7_32;
    39	    wire SLL  = Rop & funct3_1 & funct7_0;
    40	    wire SLT  = Rop & funct3_2 & funct7_0;
    41	    wire SLTU = Rop & funct3_3 & funct7_0;
    42	    wire XOR  = Rop & funct3_4 & funct7_0;
    43	    wire SRL  = Rop & funct3_5 & funct7_0;
    44	    wire SRA  = Rop & funct3_5 & funct7_32;
    45	    wire OR   = Rop & funct3_6 & funct7_0;
    46	    wire AND  = Rop & funct3_7 & funct7_0;
    47	
    48	    wire ADDI  = Iop & funct3_0;	
    49	    wire SLTI  = Iop & funct3_2;
    50	    wire SLTIU = Iop & funct3_3;
    51	    wire XORI  = Iop & funct3_4;
    52	    wire ORI   = Iop & funct3_6;
    53	    wire ANDI  = Iop & funct3_7;
    54	    wire SLLI  = Iop & funct3_1 & funct7_0;
    55	    wire SRLI  = Iop & funct3_5 & funct7_0;
    56	    wire SRAI  = Iop & funct3_5 & funct7_32;
    57	
    58	    wire BEQ  = 1'b0; // TODO: implement — decode BEQ from Bop and funct3
    59	    wire BNE  = 1'b0; // TODO: implement
    60	    wire BLT  = 1'b0; // TODO: implement
    61	    wire BGE  = 1'b0; // TODO: implement
    62	    wire BLTU = 1'b0; // TODO: implement
    63	    wire BGEU = 1'b0; // TODO: implement
    64	
    65	    wire LB  = 1'b0; // TODO: implement — decode load subtypes from Lop and funct3
    66	    wire LH  = 1'b0; // TODO: implement
    67	    wire LW  = 1'b0; // TODO: implement
    68	    wire LBU = 1'b0; // TODO: implement
    69	    wire LHU = 1'b0; // TODO: implement
    70	
    71	    wire SB = 1'b0; // TODO: implement — decode store subtypes from Sop and funct3
    72	    wire SH = 1'b0; // TODO: implement
    73	    wire SW = 1'b0; // TODO: implement
    74	
    75	    wire LUI   = 1'b0; // TODO: implement — decode from opcode
    76	    wire AUIPC = 1'b0; // TODO: implement
    77	
    78	    wire JAL  = 1'b0; // TODO: implement
    79	    assign JALR = 1'b0; // TODO: implement
    80	
    81	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
    82	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
    83	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
    84	    wire L_valid = LW | LH | LB | LHU | LBU;
    85	    wire S_valid = SW | SH | SB;
    86	
    87	
    88	    assign Branch = 1'b0; // TODO: implement — set when branch taken or unconditional jump
    89	
    90	    parameter Imm_type_I = 3'b001;
    91	    parameter Imm_type_B = 3'b010;
    92	    parameter Imm_type_J = 3'b011;
    93	    parameter Imm_type_S = 3'b100;
    94	    parameter Imm_type_U = 3'b101;
    95	    assign ImmSel = {3{I_valid | JALR | L_valid}} & Imm_type_I |
    96	                    {3{B_valid}}                  & Imm_type_B |
    97	                    {3{JAL}}                      & Imm_type_J |
    98	                    {3{S_valid}}                  & Imm_type_S |
    99	                    {3{LUI | AUIPC}}              & Imm_type_U ;
   100	
   101	
   102	    assign cmp_ctrl = 3'b000; // TODO: implement — select comparison type for cmp_32 based on branch subtype
   103	
   104	    assign ALUSrc_A = 1'b0; // TODO: implement — 1 for AUIPC/JAL/JALR (uses PC), 0 for others
   105	
   106	    assign ALUSrc_B = 1'b0; // TODO: implement — 1 for immediate-type instructions, 0 for R-type
   107	
   108	    parameter ALU_ADD  = 4'b0001;
   109	    parameter ALU_SUB  = 4'b0010;
   110	    parameter ALU_AND  = 4'b0011;
   111	    parameter ALU_OR   = 4'b0100;
   112	    parameter ALU_XOR  = 4'b0101;
   113	    parameter ALU_SLL  = 4'b0110;
   114	    parameter ALU_SRL  = 4'b0111;
   115	    parameter ALU_SLT  = 4'b1000;
   116	    parameter ALU_SLTU = 4'b1001;
   117	    parameter ALU_SRA  = 4'b1010;
   118	    parameter ALU_Ap4  = 4'b1011;
   119	    parameter ALU_Bout = 4'b1100;
   120	    assign ALUControl = {4{ADD | ADDI | L_valid | S_valid | AUIPC}} & ALU_ADD  |
   121	                        {4{SUB}}                                    & ALU_SUB  |
   122	                        {4{AND | ANDI}}                             & ALU_AND  |
   123	                        {4{OR | ORI}}                               & ALU_OR   |
   124	                        {4{XOR | XORI}}                             & ALU_XOR  |
   125	                        {4{SLL | SLLI}}                             & ALU_SLL  |
   126	                        {4{SRL | SRLI}}                             & ALU_SRL  |
   127	                        {4{SLT | SLTI}}                             & ALU_SLT  |
   128	                        {4{SLTU | SLTIU}}                           & ALU_SLTU |
   129	                        {4{SRA | SRAI}}                             & ALU_SRA  |
   130	                        {4{JAL | JALR}}                             & ALU_Ap4  |
   131	                        {4{LUI}}                                    & ALU_Bout ;
   132	
   133	    assign DatatoReg = L_valid;
   134	
   135	    assign RegWrite = R_valid | I_valid | JAL | JALR | L_valid | LUI | AUIPC;
   136	
   137	    assign mem_w = S_valid;
   138	
   139	    assign MIO = L_valid | S_valid;
   140	
   141	    assign rs1use = 1'b0; // TODO: implement — 1 for instructions that read rs1 register
   142	
   143	    assign rs2use = 1'b0; // TODO: implement — 1 for instructions that read rs2 register
   144	
   145	    assign hazard_optype = 2'b00; // TODO: implement — 2'b10 for loads, 2'b01 for other writes, 2'b00 for no write
   146	
   147	endmodule=========== core/ALU.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module ALU(
     4	    input[31:0] A, B,
     5	    input[3:0] Control,
     6	    output[31:0] res,
     7	    output zero, overflow
     8	);
     9	
    10	    parameter ALU_ADD  = 4'b0001;
    11	    parameter ALU_SUB  = 4'b0010;
    12	    parameter ALU_AND  = 4'b0011;
    13	    parameter ALU_OR   = 4'b0100;
    14	    parameter ALU_XOR  = 4'b0101;
    15	    parameter ALU_SLL  = 4'b0110;
    16	    parameter ALU_SRL  = 4'b0111;
    17	    parameter ALU_SLT  = 4'b1000;
    18	    parameter ALU_SLTU = 4'b1001;
    19	    parameter ALU_SRA  = 4'b1010;
    20	    parameter ALU_Ap4  = 4'b1011;
    21	    parameter ALU_Bout = 4'b1100;
    22	
    23	    // TODO: implement — compute the ALU result, zero flag, and overflow flag
    24	    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
    25	    // Use the Control input to select which operation to perform.
    26	    // zero should be 1 when res is all zeros.
    27	    // overflow should be set for signed ADD/SUB overflow.
    28	    assign res = 32'b0;
    29	    assign zero = 1'b0;
    30	    assign overflow = 1'b0;
    31	
    32	endmodule=========== core/ImmGen.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module ImmGen(
     4	            input  wire [2:0] ImmSel,
     5	            input  wire [31:0] inst_field,
     6	            output[31:0] Imm_out
     7	    );
     8	    parameter Imm_type_I = 3'b001;
     9	    parameter Imm_type_B = 3'b010;
    10	    parameter Imm_type_J = 3'b011;
    11	    parameter Imm_type_S = 3'b100;
    12	    parameter Imm_type_U = 3'b101;
    13	
    14	    // TODO: implement — generate the sign-extended immediate value based on ImmSel
    15	    // Must handle I-type, B-type, J-type, S-type, and U-type immediate formats
    16	    // following the RISC-V encoding specification.
    17	    assign Imm_out = 32'b0;
    18	endmodule
