`timescale 1ns / 1ps

module ALU(
    input[31:0] A, B,
    input[3:0] Control,
    output[31:0] res,
    output zero, overflow
);

    localparam ALU_ADD  = 4'b0001;
    localparam ALU_SUB  = 4'b0010;
    localparam ALU_AND  = 4'b0011;
    localparam ALU_OR   = 4'b0100;
    localparam ALU_XOR  = 4'b0101;
    localparam ALU_SLL  = 4'b0110;
    localparam ALU_SRL  = 4'b0111;
    localparam ALU_SLT  = 4'b1000;
    localparam ALU_SLTU = 4'b1001;
    localparam ALU_SRA  = 4'b1010;
    localparam ALU_Ap4  = 4'b1011;
    localparam ALU_Bout = 4'b1100;

    // 实现：根据 Control 选择运算，并生成 zero / overflow 标志
    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
    // Use the Control input to select which operation to perform.
    // zero should be 1 when res is all zeros.
    // overflow should be set for signed ADD/SUB overflow.

    wire[31:0] res_ADD  = A + B;
    wire[31:0] res_SUB  = A - B;
    wire[31:0] res_AND  = A & B;
    wire[31:0] res_OR   = A | B;
    wire[31:0] res_XOR  = A ^ B;
    wire[31:0] res_SLL  = A << B[4:0];
    wire[31:0] res_SRL  = A >> B[4:0];
    wire[31:0] res_SRA  = $signed(A) >>> B[4:0];
    wire       res_lt   = $signed(A) < $signed(B);
    wire       res_ltu  = A < B;
    wire[31:0] res_SLT  = {31'b0, res_lt};
    wire[31:0] res_SLTU = {31'b0, res_ltu};
    wire[31:0] res_Ap4  = A + 32'd4;
    wire[31:0] res_Bout = B;

    wire is_ADD  = Control == ALU_ADD ;
    wire is_SUB  = Control == ALU_SUB ;
    wire is_AND  = Control == ALU_AND ;
    wire is_OR   = Control == ALU_OR  ;
    wire is_XOR  = Control == ALU_XOR ;
    wire is_SLL  = Control == ALU_SLL ;
    wire is_SRL  = Control == ALU_SRL ;
    wire is_SLT  = Control == ALU_SLT ;
    wire is_SLTU = Control == ALU_SLTU;
    wire is_SRA  = Control == ALU_SRA ;
    wire is_Ap4  = Control == ALU_Ap4 ;
    wire is_Bout = Control == ALU_Bout;

    assign res = {32{is_ADD }} & res_ADD  |
                 {32{is_SUB }} & res_SUB  |
                 {32{is_AND }} & res_AND  |
                 {32{is_OR  }} & res_OR   |
                 {32{is_XOR }} & res_XOR  |
                 {32{is_SLL }} & res_SLL  |
                 {32{is_SRL }} & res_SRL  |
                 {32{is_SLT }} & res_SLT  |
                 {32{is_SLTU}} & res_SLTU |
                 {32{is_SRA }} & res_SRA  |
                 {32{is_Ap4 }} & res_Ap4  |
                 {32{is_Bout}} & res_Bout ;

    assign zero = ~(|res);

    assign overflow = is_ADD  & (~(A[31] ^ B[31]) & (res_ADD[31] ^ A[31])) |
                      is_SUB  & ( (A[31] ^ B[31]) & (res_SUB[31] ^ A[31])) ;

endmodule=========== core/ImmGen.v ===========
`timescale 1ns / 1ps

module ImmGen(
            input  wire [2:0] ImmSel,
            input  wire [31:0] inst_field,
            output[31:0] Imm_out
    );
    localparam Imm_type_I = 3'b001;
    localparam Imm_type_B = 3'b010;
    localparam Imm_type_J = 3'b011;
    localparam Imm_type_S = 3'b100;
    localparam Imm_type_U = 3'b101;

    // 实现：根据 ImmSel 生成符号扩展后的立即数
    // Must handle I-type, B-type, J-type, S-type, and U-type immediate formats
    // following the RISC-V encoding specification.
    wire I = ImmSel == Imm_type_I;
    wire B = ImmSel == Imm_type_B;
    wire J = ImmSel == Imm_type_J;
    wire S = ImmSel == Imm_type_S;
    wire U = ImmSel == Imm_type_U;

    wire[31:0] Imm_I = {{20{inst_field[31]}}, inst_field[31:20]};
    wire[31:0] Imm_B = {{20{inst_field[31]}}, inst_field[7], inst_field[30:25], inst_field[11:8], 1'b0};
    wire[31:0] Imm_J = {{12{inst_field[31]}}, inst_field[19:12], inst_field[20], inst_field[30:21], 1'b0};
    wire[31:0] Imm_S = {{20{inst_field[31]}}, inst_field[31:25], inst_field[11:7]};
    wire[31:0] Imm_U = {inst_field[31:12], 12'b0};

    assign Imm_out = {32{I}} & Imm_I |
                     {32{B}} & Imm_B |
                     {32{J}} & Imm_J |
                     {32{S}} & Imm_S |
                     {32{U}} & Imm_U ;
endmodule
