module     Regs(input clk,
				input rst,
				input [4:0] R_addr_A, 
				input [4:0] R_addr_B, 
				input [4:0] Wt_addr, 
				input [31:0]Wt_data, 
				input L_S, 
				output [31:0] rdata_A, 
				output [31:0] rdata_B,
				input [4:0] Debug_addr,         // debug address
				output[31:0] Debug_regs        // debug data
			  );

reg [31:0] register [1:31]; 				// r1 - r31
integer i;

	// 实现：两读一写的寄存器堆
	// - Reading two registers simultaneously (rdata_A, rdata_B)
	// - Writing one register per cycle when L_S is asserted (write to Wt_addr with Wt_data)
	// - x0 always reads as 0
	// - Synchronous reset clears all registers to 0
	// - Debug port reads register[Debug_addr] (0 if addr is 0)
	assign rdata_A = (R_addr_A == 5'b0) ? 32'b0 : register[R_addr_A];	// read
	assign rdata_B = (R_addr_B == 5'b0) ? 32'b0 : register[R_addr_B];	// read

	// 写口在时钟下降沿动作，使得同一周期 WB 写入的值可以被 ID 级立即读到
	always @(negedge clk or posedge rst)
	begin
		if (rst) begin							// reset
			for (i = 1; i < 32; i = i + 1)
				register[i] <= 32'b0;
		end
		else begin
			if ((Wt_addr != 5'b0) && (L_S == 1'b1))	// write
				register[Wt_addr] <= Wt_data;
		end
	end

	assign Debug_regs = (Debug_addr == 5'b0) ? 32'b0 : register[Debug_addr];		//TEST

endmodule


