                    output reg[4:0]  rs1_EX,
                    output reg[4:0]  rs2_EX,
                    output reg[31:0] A_EX,                             //锁存当前译码指令读出寄存器A数据
                    output reg[31:0] B_EX,                             //锁存当前译码指令读出寄存器B数据
                    output reg[31:0] Imm32_EX,                          //锁存当前译码指令32位立即数�?
                    output reg[4:0]  rd_EX,                            //锁存当前译码指令写目的寄存器地址
                    output reg       ALUSrc_A_EX,                      //锁存当前译码指令ALU A通道控制
                    output reg       ALUSrc_B_EX,                      //锁存当前译码指令ALU B通道控制(保留)
                    output reg[3:0]  ALUC_EX,                          //锁存当前译码指令ALU操作功能控制
                    output reg       DatatoReg_EX,                     //锁存当前译码指令REG写数据�?�道选择
                    output reg       RegWrite_EX,                      //锁存当前译码指令寄存器写信号
                    output reg       WR_EX,                            //锁存当前译码指令存储器读写信�?
                    output reg[2:0]  u_b_h_w_EX,
                    output reg       mem_r_EX,
                    output reg       isFlushed,
                    output reg       csr_rw_EX,
                    output reg       csr_w_imm_mux_EX,
                    output reg       mret_EX,
                    output reg[1:0]  exp_vector_EX
                );

    // 实现：ID/EX 流水寄存器
    // On reset: clear rd_EX, RegWrite_EX, WR_EX, IR_EX, PCurrent_EX, rs1_EX, rs2_EX,
    //   mem_r_EX, isFlushed, csr_rw_EX, mret_EX, exp_vector_EX to 0.
    // When EN is asserted:
    //   - If flush: insert a pipeline bubble — set IR_EX to NOP (32'h00000000), clear rd_EX,
    //     RegWrite_EX, WR_EX, mem_r_EX, csr_rw_EX, mret_EX, exp_vector_EX to 0,
    //     set isFlushed to 1, but still pass PCurrent_ID to PCurrent_EX.
    //   - Else: latch all input signals to their corresponding output registers.
    always @(posedge clk) begin
        if (rst) begin
            PCurrent_EX      <= 32'b0;
            IR_EX            <= 32'b0;
            rs1_EX           <= 5'b0;
            rs2_EX           <= 5'b0;
            A_EX             <= 32'b0;
            B_EX             <= 32'b0;
            Imm32_EX         <= 32'b0;
            rd_EX            <= 5'b0;
            ALUSrc_A_EX      <= 1'b0;
            ALUSrc_B_EX      <= 1'b0;
            ALUC_EX          <= 4'b0;
