            u_b_h_w_EX       <= 3'b0;
            mem_r_EX         <= 1'b0;
            isFlushed        <= 1'b0;
            csr_rw_EX        <= 1'b0;
            csr_w_imm_mux_EX <= 1'b0;
            mret_EX          <= 1'b0;
            exp_vector_EX    <= 2'b0;
