                PCurrent_EX      <= PCurrent_ID;
                IR_EX            <= 32'h00000000;
                rs1_EX           <= 5'b0;
                rs2_EX           <= 5'b0;
                A_EX             <= 32'b0;
                B_EX             <= 32'b0;
                Imm32_EX         <= 32'b0;
                rd_EX            <= 5'b0;
                ALUSrc_A_EX      <= 1'b0;
                ALUSrc_B_EX      <= 1'b0;
                ALUC_EX          <= 4'b0;
                DatatoReg_EX     <= 1'b0;
                RegWrite_EX      <= 1'b0;
                WR_EX            <= 1'b0;
                u_b_h_w_EX       <= 3'b0;
                mem_r_EX         <= 1'b0;
                isFlushed        <= 1'b1;
                csr_rw_EX        <= 1'b0;
                csr_w_imm_mux_EX <= 1'b0;
                mret_EX          <= 1'b0;
                exp_vector_EX    <= 2'b0;
            end
            else begin
                PCurrent_EX      <= PCurrent_ID;
                IR_EX            <= IR_ID;
                rs1_EX           <= rs1_addr;
                rs2_EX           <= rs2_addr;
                A_EX             <= rs1_data;
                B_EX             <= rs2_data;
