`timescale 1ns / 1ps
// 简单的轨迹打印 testbench，用于人工检查流水线行为
module trace_tb;
    reg clk, rst;
    wire [31:0] debug_data, pc, inst, mem_addr, mem_data;

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'd0), .debug_data(debug_data),
        .clk(clk), .rst(rst), .interrupter(1'b0),
        .pc(pc), .inst(inst), .mem_addr(mem_addr), .mem_data(mem_data)
    );

    integer n;
    initial begin
        clk = 0; rst = 1; n = 0;
        #2 rst = 0;
    end
    always #1 clk = ~clk;

    always @(posedge clk) begin
        if (!rst) begin
            n = n + 1;
            $display("cyc=%0d  PC_IF=%h inst_ID=%h PC_ID=%h | stall=%b flushFD=%b fwdA=%b fwdB=%b | EX rd=%0d MEM rd=%0d | WB: PC=%h inst=%h rd=%0d wt=%h we=%b",
                n, core.PC_IF, core.inst_ID, core.PC_ID,
                core.hazard_unit.stall, core.reg_FD_flush, core.forward_ctrl_A, core.forward_ctrl_B,
                core.rd_EXE, core.rd_MEM,
                core.PC_WB, core.inst_WB, core.rd_WB, core.wt_data_WB, core.RegWrite_WB);
            if (n > 130) $finish;
        end
    end
endmodule

`timescale 1ns / 1ps
//
// Self-checking testbench for src/lab1 (RV32I 5-stage pipeline).
//
// Expectations are taken directly from src/lab1/all_test.s, which documents the
// PC and the resulting register value of (nearly) every instruction, plus the
// documented control flow (which branches are taken) and the memory section.
//
// Three independent checks are performed:
//   A) retired write-back trace : (PC_WB, rd_WB, wt_data_WB) for every retiring
//      instruction that asserts RegWrite_WB with rd != x0, in order.
//   B) executed PC stream       : the sequence of PCs that actually make it into
//      the ID stage (i.e. not squashed by a taken branch, and de-duplicated
//      across stall cycles).  This validates every taken/not-taken branch,
//      the JAL/JALR targets and the final loop back to PC = 0.
//   C) final data-memory image  : the bytes written by sw / sh / sb.
//
module lab1_tb;

    reg clk, rst;
    wire [31:0] debug_data, pc, inst, mem_addr, mem_data;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(debug_data),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0),
        .pc(pc),
        .inst(inst),
        .mem_addr(mem_addr),
        .mem_data(mem_data)
    );

    // ------------------------------------------------------------------
    // A) expected write-back trace (41 register writes, all_test.s pass 1)
    // ------------------------------------------------------------------
    localparam NW = 41;
    reg [31:0] e_pc  [0:NW-1];
    reg [4:0]  e_rd  [0:NW-1];
    reg [31:0] e_val [0:NW-1];
    reg [8*10-1:0] e_nm [0:NW-1];

    // ------------------------------------------------------------------
    // B) expected executed-PC stream (59 instructions + loop back to 0)
    // ------------------------------------------------------------------
    localparam NP = 60;
    reg [31:0] e_ps [0:NP-1];

    integer i;
    integer wi, pi;
    integer errors;
    integer cyc;
    integer wdone, pdone;

    task expw(input integer k, input [31:0] p, input [4:0] r,
              input [31:0] v, input [8*10-1:0] nm);
        begin e_pc[k] = p; e_rd[k] = r; e_val[k] = v; e_nm[k] = nm; end
    endtask

    initial begin
        // ---- expected register writes, in retirement order --------------
        expw( 0, 32'h004, 5'd2 , 32'h00000008, "lw   ");
        expw( 1, 32'h008, 5'd4 , 32'h00000010, "lw   ");
        expw( 2, 32'h00C, 5'd1 , 32'h00000018, "add  ");
        expw( 3, 32'h010, 5'd1 , 32'h00000017, "addi ");
        expw( 4, 32'h014, 5'd5 , 32'h00000014, "lw   ");
        expw( 5, 32'h018, 5'd6 , 32'hFFFF0000, "lw   ");
        expw( 6, 32'h01C, 5'd7 , 32'h0FFF0000, "lw   ");
        expw( 7, 32'h020, 5'd1 , 32'h00000008, "sub  ");
        expw( 8, 32'h024, 5'd1 , 32'h00000000, "and  ");
        expw( 9, 32'h028, 5'd1 , 32'h00000018, "or   ");
        expw(10, 32'h02C, 5'd1 , 32'h00000018, "xor  ");
        expw(11, 32'h030, 5'd1 , 32'h00001000, "sll  ");
        expw(12, 32'h034, 5'd1 , 32'h00000000, "slt  ");
        expw(13, 32'h038, 5'd1 , 32'h00000001, "slt  ");
        expw(14, 32'h03C, 5'd1 , 32'h00FFFF00, "srl  ");
        expw(15, 32'h040, 5'd1 , 32'hFFFFFF00, "sra  ");
        expw(16, 32'h044, 5'd1 , 32'h000FFF00, "sra  ");
        expw(17, 32'h048, 5'd1 , 32'h00000000, "sltu ");
        expw(18, 32'h04C, 5'd1 , 32'h00000001, "sltu ");
        expw(19, 32'h054, 5'd1 , 32'hFFFFFFFD, "addi ");
        expw(20, 32'h058, 5'd1 , 32'h00000000, "andi ");
        expw(21, 32'h05C, 5'd1 , 32'h0000001F, "ori  ");
        expw(22, 32'h060, 5'd1 , 32'h0000001F, "xori ");
        expw(23, 32'h064, 5'd1 , 32'h00000000, "slti ");
        expw(24, 32'h068, 5'd1 , 32'h00000020, "slli ");
        expw(25, 32'h06C, 5'd1 , 32'h00000004, "srli ");
        expw(26, 32'h070, 5'd1 , 32'hFFFFFFF0, "srai ");
        expw(27, 32'h074, 5'd1 , 32'h00000001, "sltiu");
        expw(28, 32'h078, 5'd1 , 32'h00000001, "sltiu");
        expw(29, 32'h0E8, 5'd1 , 32'h00004000, "lui  ");
        expw(30, 32'h0EC, 5'd1 , 32'h000000F0, "jal  ");
        expw(31, 32'h0F8, 5'd8 , 32'hFF000F0F, "lw   ");
        expw(32, 32'h100, 5'd1 , 32'hFF000F0F, "lw   ");
        expw(33, 32'h108, 5'd1 , 32'h00000F0F, "lw   ");
        expw(34, 32'h110, 5'd1 , 32'h0000000F, "lw   ");
        expw(35, 32'h114, 5'd1 , 32'hFFFFFF00, "lh   ");
        expw(36, 32'h118, 5'd1 , 32'h0000FF00, "lhu  ");
        expw(37, 32'h11C, 5'd1 , 32'hFFFFFFFF, "lb   ");
        expw(38, 32'h120, 5'd1 , 32'h000000FF, "lbu  ");
        expw(39, 32'h124, 5'd1 , 32'hFFFF0124, "auipc");
        expw(40, 32'h128, 5'd1 , 32'h0000012C, "jalr ");

        // ---- expected executed PC stream --------------------------------
        // straight line 0x00 .. 0x7C
        for (i = 0; i < 32; i = i + 1) e_ps[i] = i * 4;          // 0x00 .. 0x7C
        e_ps[32] = 32'h080;   // beq x4,x4,label0  -> taken, 0x84/0x88 skipped
        e_ps[33] = 32'h08C;
        e_ps[34] = 32'h090;   // bne x4,x5,label1  -> taken
        e_ps[35] = 32'h09C;
        e_ps[36] = 32'h0A0;   // blt x4,x5,label2  -> taken
        e_ps[37] = 32'h0AC;
        e_ps[38] = 32'h0B0;   // bltu x7,x6,label3 -> taken
        e_ps[39] = 32'h0BC;
        e_ps[40] = 32'h0C0;   // bge x5,x4,label4  -> taken
        e_ps[41] = 32'h0CC;
        e_ps[42] = 32'h0D0;   // bgeu x6,x7,label5 -> taken
        e_ps[43] = 32'h0DC;   // bge x4,x4,label6  -> taken
        e_ps[44] = 32'h0E8;
        e_ps[45] = 32'h0EC;   // jal x1,12         -> 0xF8, 0xF0/0xF4 skipped
        e_ps[46] = 32'h0F8;
        e_ps[47] = 32'h0FC;
        e_ps[48] = 32'h100;
        e_ps[49] = 32'h104;
        e_ps[50] = 32'h108;
        e_ps[51] = 32'h10C;
        e_ps[52] = 32'h110;
        e_ps[53] = 32'h114;
        e_ps[54] = 32'h118;
        e_ps[55] = 32'h11C;
        e_ps[56] = 32'h120;
        e_ps[57] = 32'h124;
        e_ps[58] = 32'h128;   // jalr x1,0(x0)     -> back to 0
        e_ps[59] = 32'h000;
    end

    // ------------------------------------------------------------------
    // clock / reset
    // ------------------------------------------------------------------
    initial begin
        clk = 0; rst = 1;
        #2 rst = 0;
    end
    always #1 clk = ~clk;

    initial begin
        wi = 0; pi = 0; errors = 0; cyc = 0; wdone = 0; pdone = 0;
        $display("=========================================================================");
        $display(" lab1 RV32I 5-stage pipeline self-check");
        $display("=========================================================================");
        $display("");
        $display("--- A) retired write-back trace -----------------------------------------");
        $display("  #  inst    PC        rd   expected    actual      result");
    end

    // ------------------------------------------------------------------
    // checks
    // ------------------------------------------------------------------
    always @(posedge clk) if (!rst) begin
        cyc = cyc + 1;

        // ---- A) write-back trace ------------------------------------
        if (core.RegWrite_WB === 1'b1 && core.rd_WB !== 5'd0 && !wdone) begin
            if (wi < NW) begin
                if (core.PC_WB === e_pc[wi] && core.rd_WB === e_rd[wi] &&
                    core.wt_data_WB === e_val[wi]) begin
                    $display("  %0d\t%0s   0x%03h    x%0d\t%h    %h    PASS",
                        wi, e_nm[wi], e_pc[wi], e_rd[wi], e_val[wi], core.wt_data_WB);
                end
                else begin
                    errors = errors + 1;
                    $display("  %0d\t%0s   0x%03h    x%0d\t%h    %h    *** FAIL ***  (got PC=%h rd=x%0d)",
                        wi, e_nm[wi], e_pc[wi], e_rd[wi], e_val[wi],
                        core.wt_data_WB, core.PC_WB, core.rd_WB);
                end
                wi = wi + 1;
                if (wi == NW) wdone = 1;
            end
        end

        // ---- B) executed PC stream ----------------------------------
        // IF/ID latches a fresh instruction whenever it is neither stalled
        // nor squashed, so PC_IF at that moment is a genuinely executed PC.
        if (core.reg_FD_EN === 1'b1 && core.reg_FD_stall === 1'b0 &&
            core.reg_FD_flush === 1'b0 && !pdone) begin
            if (pi < NP) begin
                if (core.PC_IF !== e_ps[pi]) begin
                    errors = errors + 1;
                    $display("  [PC stream] step %0d: expected PC=0x%03h, got 0x%08h  *** FAIL ***",
                        pi, e_ps[pi], core.PC_IF);
                end
                pi = pi + 1;
                if (pi == NP) pdone = 1;
            end
        end

        if (cyc > 400) begin
            $display("*** TIMEOUT: simulation ran %0d cycles without completing ***", cyc);
            errors = errors + 1;
            report;
            $finish;
        end
        if (wdone && pdone) begin
            report;
            $finish;
        end
    end

    // ------------------------------------------------------------------
    // final report
    // ------------------------------------------------------------------
    reg [7:0] m;
    task chkmem(input integer addr, input [7:0] exp);
        begin
            m = core.data_ram.data[addr];
            if (m === exp)
                $display("  ram[%0d]\t= %h   expected %h    PASS", addr, m, exp);
            else begin
                errors = errors + 1;
                $display("  ram[%0d]\t= %h   expected %h    *** FAIL ***", addr, m, exp);
            end
        end
    endtask

    task report;
        begin
            $display("");
            $display("--- B) executed PC stream ------------------------------------------------");
            if (pi < NP) begin
                errors = errors + 1;
                $display("  only %0d of %0d expected PCs were observed   *** FAIL ***", pi, NP);
            end
            else
                $display("  all %0d executed PCs matched (branches, JAL/JALR targets, loop to 0)   PASS", NP);
            $display("");
            $display("--- C) final data-memory image (sw/sh/sb results) ------------------------");
            // sw x8, 28(x0) : 0xFF000F0F -> bytes 28..31 (little endian)
            chkmem(28, 8'h0F); chkmem(29, 8'h0F);
            chkmem(30, 8'h00); chkmem(31, 8'hFF);
            // sh x8, 32(x0) : low half 0x0F0F -> bytes 32..33 ; 34..35 untouched
            chkmem(32, 8'h0F); chkmem(33, 8'h0F);
            chkmem(34, 8'h00); chkmem(35, 8'h00);
            // sb x8, 36(x0) : low byte 0x0F -> byte 36 ; 37..39 untouched
            chkmem(36, 8'h0F); chkmem(37, 8'h00);
            chkmem(38, 8'h00); chkmem(39, 8'h00);
            // untouched source data must survive
            chkmem(24, 8'h0F); chkmem(25, 8'h0F);
            chkmem(26, 8'h00); chkmem(27, 8'hFF);
            $display("");
            $display("--- summary --------------------------------------------------------------");
            $display("  write-back checks : %0d / %0d", wi, NW);
            $display("  PC-stream checks  : %0d / %0d", pi, NP);
            $display("  cycles simulated  : %0d", cyc);
            if (errors == 0)
                $display("  OVERALL: PASS  (0 errors)");
            else
                $display("  OVERALL: FAIL  (%0d errors)", errors);
            $display("=========================================================================");
        end
    endtask

endmodule

