    parameter ALU_Ap4  = 4'b1011;
    parameter ALU_Bout = 4'b1100;
    assign ALUControl = {4{ADD | ADDI | L_valid | S_valid | AUIPC}} & ALU_ADD  |
                        {4{SUB}}                                    & ALU_SUB  |
                        {4{AND | ANDI}}                             & ALU_AND  |
                        {4{OR | ORI}}                               & ALU_OR   |
                        {4{XOR | XORI}}                             & ALU_XOR  |
                        {4{SLL | SLLI}}                             & ALU_SLL  |
                        {4{SRL | SRLI}}                             & ALU_SRL  |
                        {4{SLT | SLTI}}                             & ALU_SLT  |
                        {4{SLTU | SLTIU}}                           & ALU_SLTU |
                        {4{SRA | SRAI}}                             & ALU_SRA  |
                        {4{JAL | JALR}}                             & ALU_Ap4  |
                        {4{LUI}}                                    & ALU_Bout ;

    assign DatatoReg = L_valid;

    assign RegWrite = R_valid | I_valid | JAL | JALR | L_valid | LUI | AUIPC;

    assign mem_w = S_valid;

    assign MIO = L_valid | S_valid;

    // 实现：读取 rs1 的指令
    assign rs1use = R_valid | I_valid | L_valid | S_valid | B_valid | JALR;

    // 实现：读取 rs2 的指令
    assign rs2use = R_valid | S_valid | B_valid;

    localparam hazard_optype_NONE = 2'b00;   // 不写寄存器
    localparam hazard_optype_ALU   = 2'b01;   // 结果在 EX 段产生
    localparam hazard_optype_LOAD  = 2'b10;   // 结果在 MEM 段产生
    // 实现：load 为 2'b10，其它写寄存器的指令为 2'b01，其余为 2'b00
    assign hazard_optype = {2{L_valid}} & hazard_optype_LOAD |
                           {2{R_valid | I_valid | LUI | AUIPC | JAL | JALR}} & hazard_optype_ALU ;

endmodule
